window.IDE2_DRIVE_QUESTIONS=(window.IDE2_DRIVE_QUESTIONS||[]).concat([{"id":"PARTIEL-20261125-1","ue":"B.1","topic":"Sémiologie — digestif","difficulty":2,"type":"multi","q":"Concernant les signes fonctionnels digestifs, quelles propositions sont exactes ?","choices":["La dysphagie désigne une difficulté à déglutir.","L’odynophagie désigne une déglutition douloureuse.","Le méléna correspond à du sang rouge non digéré dans les selles.","L’hématémèse est un vomissement de sang.","Une douleur épigastrique est nécessairement digestive."],"answers":[0,1,3],"exp":"<p><b>A — Vrai</b> : La dysphagie concerne le passage du bol alimentaire.</p><p><b>B — Vrai</b> : Elle caractérise la douleur lors de la déglutition.</p><p><b>C — Faux</b> : Le méléna correspond à des selles noires contenant du sang digéré.</p><p><b>D — Vrai</b> : Le sang est expulsé par vomissement.</p><p><b>E — Faux</b> : Une origine cardiaque est également possible.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-2","ue":"B.1","topic":"Sémiologie — urinaire","difficulty":2,"type":"multi","q":"Concernant les signes urinaires, coche les propositions exactes.","choices":["La pollakiurie correspond à des mictions fréquentes de faible volume.","La polyurie correspond à une augmentation du volume urinaire.","La dysurie correspond à une difficulté à uriner.","L’hématurie correspond à la présence de pus dans les urines.","Une rétention aiguë d’urine est synonyme d’anurie."],"answers":[0,1,2],"exp":"<p><b>A — Vrai</b> : Elle concerne la fréquence des mictions.</p><p><b>B — Vrai</b> : Elle concerne le volume total.</p><p><b>C — Vrai</b> : Elle concerne la vidange vésicale.</p><p><b>D — Faux</b> : Elle désigne la présence de sang.</p><p><b>E — Faux</b> : La rétention concerne la vidange, l’anurie la quantité d’urine produite.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-3","ue":"B.1","topic":"Sémiologie — respiratoire","difficulty":2,"type":"multi","q":"Concernant la sémiologie respiratoire, quelles propositions sont exactes ?","choices":["L’orthopnée est une dyspnée en position allongée.","Une toux productive s’accompagne d’expectorations.","Une douleur pleurale peut être majorée à l’inspiration.","L’hémoptysie est un vomissement de sang.","Une dyspnée est toujours d’origine pulmonaire."],"answers":[0,1,2],"exp":"<p><b>A — Vrai</b> : Elle est notamment observée dans certaines affections cardiaques.</p><p><b>B — Vrai</b> : Elle permet l’expulsion de sécrétions.</p><p><b>C — Vrai</b> : Les mouvements respiratoires mobilisent la plèvre.</p><p><b>D — Faux</b> : Il s’agit de sang provenant des voies respiratoires et rejeté par la bouche.</p><p><b>E — Faux</b> : Elle peut notamment être cardiaque.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-4","ue":"B.1","topic":"Biologie cellulaire — organites","difficulty":2,"type":"multi","q":"Concernant la cellule eucaryote, quelles propositions sont exactes ?","choices":["Le REL porte des ribosomes fixés.","Le Golgi participe au tri des protéines.","Les lysosomes participent au recyclage intracellulaire.","La mitochondrie contient de l’ADN mitochondrial.","Le nucléole est entouré d’une membrane propre."],"answers":[1,2,3],"exp":"<p><b>A — Faux</b> : C’est le REG qui porte des ribosomes.</p><p><b>B — Vrai</b> : Il assure maturation, tri et adressage.</p><p><b>C — Vrai</b> : Ils contiennent des enzymes de dégradation.</p><p><b>D — Vrai</b> : Elle possède son propre ADN.</p><p><b>E — Faux</b> : Le nucléole est un compartiment non membranaire.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-5","ue":"B.1","topic":"Génétique — division cellulaire","difficulty":2,"type":"multi","q":"Concernant le cycle cellulaire, quelles propositions sont exactes ?","choices":["La réplication de l’ADN a lieu en phase S.","La ploïdie double en phase S.","La méiose comporte deux divisions successives.","La mitose produit normalement quatre cellules haploïdes.","Les microtubules participent au fuseau mitotique."],"answers":[0,2,4],"exp":"<p><b>A — Vrai</b> : La phase S est la phase de synthèse de l’ADN.</p><p><b>B — Faux</b> : La quantité d’ADN double, mais la ploïdie ne change pas.</p><p><b>C — Vrai</b> : Une réplication est suivie de deux divisions.</p><p><b>D — Faux</b> : Elle produit deux cellules filles de même ploïdie.</p><p><b>E — Vrai</b> : Le fuseau contribue à la séparation des chromosomes.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-6","ue":"B.1","topic":"Pharmacologie — galénique & voies","difficulty":2,"type":"multi","q":"Concernant les formes et voies d’administration, quelles propositions sont exactes ?","choices":["La voie sublinguale peut éviter le premier passage hépatique.","Une forme LP peut toujours être écrasée.","Une forme gastro-résistante protège le principe actif du milieu gastrique.","Une application locale exclut tout effet systémique.","La voie rectale peut subir un premier passage hépatique partiel."],"answers":[0,2,4],"exp":"<p><b>A — Vrai</b> : Le drainage veineux permet un accès systémique direct.</p><p><b>B — Faux</b> : L’écrasement peut modifier la libération du principe actif.</p><p><b>C — Vrai</b> : Son enrobage retarde la libération.</p><p><b>D — Faux</b> : Une absorption systémique reste possible.</p><p><b>E — Vrai</b> : Le drainage veineux rectal est mixte.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-7","ue":"B.1","topic":"Pharmacovigilance","difficulty":2,"type":"multi","q":"Concernant la pharmacovigilance, quelles propositions sont exactes ?","choices":["Un effet attendu est décrit dans le RCP.","Un effet attendu ne peut jamais être grave.","Les patients peuvent effectuer un signalement.","L’imputabilité évalue le lien entre médicament et événement.","La notification spontanée permet de calculer directement la fréquence réelle des effets."],"answers":[0,2,3],"exp":"<p><b>A — Vrai</b> : Le RCP est la référence.</p><p><b>B — Faux</b> : La gravité est indépendante du caractère attendu.</p><p><b>C — Vrai</b> : Le signalement est ouvert aux patients.</p><p><b>D — Vrai</b> : Elle apprécie la responsabilité possible du médicament.</p><p><b>E — Faux</b> : La sous-notification et l’absence de dénominateur fiable limitent cette estimation.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-8","ue":"B.1","topic":"Hygiène — IAS & précautions standard","difficulty":2,"type":"multi","q":"Concernant les précautions standard, quelles propositions sont exactes ?","choices":["Elles s’appliquent indépendamment du statut infectieux.","Les gants remplacent la friction hydroalcoolique.","Les EPI sont choisis selon le risque d’exposition.","Les aiguilles doivent être recapuchonnées avant élimination.","Le tri des déchets se fait au lieu de production."],"answers":[0,2,4],"exp":"<p><b>A — Vrai</b> : Elles constituent le socle universel.</p><p><b>B — Faux</b> : Ils ne remplacent jamais l’hygiène des mains.</p><p><b>C — Vrai</b> : Le choix dépend du geste et du risque.</p><p><b>D — Faux</b> : Le recapuchonnage expose à un accident.</p><p><b>E — Vrai</b> : Cela limite les manipulations et les risques.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-9","ue":"A.1","topic":"Sciences infirmières — paradigmes de soin","difficulty":2,"type":"multi","q":"Concernant les paradigmes de soin, quelles propositions sont exactes ?","choices":["La catégorisation est associée au faire-pour.","L’intégration est associée au faire-avec.","La transformation est associée à l’être-avec.","Le paradigme est une procédure technique détaillée.","Le métaparadigme se limite à la pathologie."],"answers":[0,1,2],"exp":"<p><b>A — Vrai</b> : Elle cible les problèmes et les actions.</p><p><b>B — Vrai</b> : Elle intègre les dimensions de la personne.</p><p><b>C — Vrai</b> : Elle considère l’expérience singulière.</p><p><b>D — Faux</b> : C’est un cadre de pensée.</p><p><b>E — Faux</b> : Il articule personne, santé, environnement et soin.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-10","ue":"D.1","topic":"Relation de soin — écoute active","difficulty":2,"type":"multi","q":"Concernant l’écoute active, quelles propositions sont exactes ?","choices":["La congruence implique une posture authentique.","La reformulation permet de vérifier la compréhension.","La non-directivité consiste à imposer une solution.","Le respect des silences peut favoriser l’expression.","L’interprétation du soignant constitue nécessairement un fait."],"answers":[0,1,3],"exp":"<p><b>A — Vrai</b> : Elle renvoie à l’authenticité.</p><p><b>B — Vrai</b> : Elle rend possible une clarification.</p><p><b>C — Faux</b> : Elle évite de diriger arbitrairement la personne.</p><p><b>D — Vrai</b> : Il laisse du temps à la personne.</p><p><b>E — Faux</b> : Une interprétation reste une hypothèse.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-11","ue":"B.3","topic":"Surveillance infirmière","difficulty":2,"type":"multi","q":"Concernant la surveillance infirmière, quelles propositions sont exactes ?","choices":["Elle se limite à mesurer les constantes.","Le suivi permet d’apprécier une évolution dans le temps.","L’évaluation compare les résultats obtenus aux résultats attendus.","Une procédure décrit les modalités de réalisation d’une action.","Les données probantes dispensent de considérer les préférences du patient."],"answers":[1,2,3],"exp":"<p><b>A — Faux</b> : Elle comprend recueil, analyse et action.</p><p><b>B — Vrai</b> : Il s’intéresse à la trajectoire clinique.</p><p><b>C — Vrai</b> : Elle apprécie l’atteinte de l’objectif.</p><p><b>D — Vrai</b> : Elle précise comment réaliser l’activité.</p><p><b>E — Faux</b> : La décision clinique intègre aussi expertise et préférences.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true},{"id":"PARTIEL-20261125-12","ue":"B.3","topic":"Gérontologie — vieillissement & fragilité","difficulty":2,"type":"multi","q":"Concernant la fragilité de la personne âgée, quelles propositions sont exactes ?","choices":["La perte de poids involontaire peut être un critère de fragilité.","La lenteur de marche peut être un critère de fragilité.","L’âge seul suffit à établir la dépendance.","La faiblesse musculaire peut contribuer au risque de chute.","Faire systématiquement à la place du résident préserve son autonomie."],"answers":[0,1,3],"exp":"<p><b>A — Vrai</b> : Elle appartient aux critères du cours.</p><p><b>B — Vrai</b> : Elle traduit une diminution des réserves fonctionnelles.</p><p><b>C — Faux</b> : Les capacités doivent être évaluées individuellement.</p><p><b>D — Vrai</b> : Elle affecte la mobilité et la stabilité.</p><p><b>E — Faux</b> : Il faut soutenir les capacités restantes.</p>","hint":"Examine chaque proposition séparément : une seule erreur suffit à rendre une affirmation fausse.","partiel":true}]);